import { MeshPhysicalNodeMaterial, MeshBasicNodeMaterial } from 'three/webgpu';
import {
  uv,
  vec2,
  vec3,
  fract,
  sin,
  dot,
  mix,
  texture,
  smoothstep,
} from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const {
    Group,
    Mesh,
    BoxGeometry,
    DataTexture,
    RGBAFormat,
    UnsignedByteType,
    DoubleSide,
    DirectionalLight,
    SRGBColorSpace,
  } = ctx.THREE;

  const colors =
    config.intent?.visualSpec?.colors ??
    config.visual?.colors ?? {
      ink: '#16161d',
      paper: '#e8ecf2',
      accent: '#ff2a38',
      surface: '#0b0b10',
    };

  const imageUrl =
    config.imageUrl ?? config.intent?.visualSpec?.imageUrl ?? null;

  const root = new Group();
  root.name = 'feature-card-1';

  // --- dimensions from atlas rect aspect (512x320 -> 1.6:1) ---
  const rectAspect = 512 / 320;
  const cardWidth = 3.0;
  const cardHeight = cardWidth / rectAspect;
  const cardDepth = 0.08;

  // --- placeholder texture (ink-tinted) so no white flash before load ---
  const inkColor = new ctx.THREE.Color(colors.ink);
  const placeholderData = new Uint8Array([
    Math.round(inkColor.r * 255),
    Math.round(inkColor.g * 255),
    Math.round(inkColor.b * 255),
    255,
  ]);
  const placeholderTex = new DataTexture(
    placeholderData,
    1,
    1,
    RGBAFormat,
    UnsignedByteType
  );
  placeholderTex.needsUpdate = true;

  const texNode = texture(placeholderTex);

  // --- procedural grain + vignette overlay (TSL only) ---
  const uvNode = uv();
  const centered = uvNode.sub(vec2(0.5, 0.5));
  const vignette = smoothstep(0.15, 0.55, centered.length());
  const grain = fract(
    sin(dot(uvNode.mul(521.0), vec2(12.9898, 78.233))).mul(43758.5453)
  )
    .sub(0.5)
    .mul(0.035);

  const inkVec = vec3(inkColor.r, inkColor.g, inkColor.b);
  const vignetted = mix(texNode.rgb, inkVec, vignette.mul(0.35));
  const grained = vignetted.add(grain);

  // --- front face: machined-metal PBR card ---
  const cardMat = new MeshPhysicalNodeMaterial({
    roughness: 0.55,
    metalness: 0.32,
    clearcoat: 0.15,
    clearcoatRoughness: 0.35,
    side: DoubleSide,
  });
  cardMat.colorNode = grained;

  const cardGeo = new BoxGeometry(cardWidth, cardHeight, cardDepth);
  const cardMesh = new Mesh(cardGeo, cardMat);
  root.add(cardMesh);

  // --- backing plate (depth plane #1: backdrop bezel) ---
  const plateMat = new MeshPhysicalNodeMaterial({
    color: colors.surface,
    roughness: 0.6,
    metalness: 0.4,
    clearcoat: 0.1,
    side: DoubleSide,
  });
  const plateGeo = new BoxGeometry(
    cardWidth + 0.14,
    cardHeight + 0.14,
    cardDepth * 0.6
  );
  const plateMesh = new Mesh(plateGeo, plateMat);
  plateMesh.position.z = -cardDepth * 0.7;
  root.add(plateMesh);

  // --- accent bar (depth plane #2: foreground accent, <=10% of frame) ---
  const accentMat = new MeshPhysicalNodeMaterial({
    color: colors.accent,
    roughness: 0.5,
    metalness: 0.2,
    emissive: colors.accent,
    emissiveIntensity: 0.9,
  });
  const accentGeo = new BoxGeometry(cardWidth * 0.32, 0.045, cardDepth * 1.4);
  const accentMesh = new Mesh(accentGeo, accentMat);
  accentMesh.position.set(
    -cardWidth / 2 + cardWidth * 0.16 + 0.08,
    cardHeight / 2 - 0.12,
    cardDepth * 0.9
  );
  root.add(accentMesh);

  // --- node-local rim light carrying accent hue ---
  const rimLight = new DirectionalLight(colors.accent, 0.55);
  rimLight.position.set(-1.5, 0.6, -2.0);
  root.add(rimLight);

  // --- node-local subtle fill so metal has something to reflect ---
  const fillLight = new DirectionalLight(colors.paper, 0.4);
  fillLight.position.set(1.2, 1.0, 1.5);
  root.add(fillLight);

  // async texture swap
  let disposed = false;
  if (imageUrl) {
    ctx.textureLoader.loadTexture(imageUrl).then((tex) => {
      if (disposed) return;
      tex.colorSpace = SRGBColorSpace;
      texNode.value = tex;
    });
  }

  // --- entrance motion: weighted settle, one-time (static composition, no idle loop) ---
  root.scale.setScalar(0.97);
  root.position.y += -0.08;
  const tl = gsap.timeline();
  tl.to(root.scale, {
    x: 1,
    y: 1,
    z: 1,
    duration: 0.9,
    ease: 'power4.out',
  });
  tl.to(
    root.position,
    {
      y: root.position.y + 0.08,
      duration: 0.7,
      ease: 'power3.out',
    },
    0
  );

  root.userData.handlers = {};

  root.userData.cleanup = () => {
    disposed = true;
    tl.kill();
    cardGeo.dispose();
    cardMat.dispose();
    plateGeo.dispose();
    plateMat.dispose();
    accentGeo.dispose();
    accentMat.dispose();
    placeholderTex.dispose();
    if (texNode.value && texNode.value !== placeholderTex) {
      texNode.value.dispose?.();
    }
    root.remove(rimLight, fillLight);
  };

  return root;
}
